// Code «Limpiar y clasificar» · Run Once for All Items
// Lee las filas de los dos CSV, las limpia (solo formato, sin recalcular importes)
// y devuelve UN item con el plan: apartados (con sus abonos), ventas, dudosos, omitidas y rango de fechas.

const ABONO_MINIMO = 5;
const FORMAS_PAGO = ['efectivo', 'tarjeta', 'bizum'];

// ---------- Limpieza ----------

// dd/MM/yyyy o d/M/yy → yyyy-MM-dd. Devuelve null si no es una fecha válida.
function limpiarFecha(valor) {
  const m = String(valor ?? '').trim().match(/^(\d{1,2})\/(\d{1,2})\/(\d{2}|\d{4})$/);
  if (!m) return null;
  const dia = Number(m[1]);
  const mes = Number(m[2]);
  const anio = m[3].length === 2 ? 2000 + Number(m[3]) : Number(m[3]);
  const f = new Date(Date.UTC(anio, mes - 1, dia));
  if (f.getUTCFullYear() !== anio || f.getUTCMonth() !== mes - 1 || f.getUTCDate() !== dia) return null;
  return `${anio}-${String(mes).padStart(2, '0')}-${String(dia).padStart(2, '0')}`;
}

// «15€» → 15 · «1.842,30» → 1842.3 · «6.50» → 6.5. Devuelve null si no es un número.
function limpiarImporte(valor) {
  let t = String(valor ?? '').replace(/€/g, '').replace(/\s/g, '');
  if (t.includes(',')) t = t.replace(/\./g, '').replace(',', '.');
  if (!/^\d+(\.\d+)?$/.test(t)) return null;
  return Number(t);
}

// «carmen  ruiz» → «Carmen Ruiz»
function limpiarNombre(valor) {
  return String(valor ?? '').trim().replace(/\s+/g, ' ').toLocaleLowerCase('es')
    .split(' ').map(p => p.charAt(0).toLocaleUpperCase('es') + p.slice(1)).join(' ');
}

// «612345002» → «612 345 002» · vacío → null
function limpiarTelefono(valor) {
  const t = String(valor ?? '').trim();
  if (!t) return null;
  const digitos = t.replace(/\D/g, '');
  return digitos.length === 9 ? `${digitos.slice(0, 3)} ${digitos.slice(3, 6)} ${digitos.slice(6)}` : t;
}

const limpiarTexto = v => String(v ?? '').trim().replace(/\s+/g, ' ');
const centimos = n => Math.round(n * 100);

const dudosos = [];
const omitidas = [];

// Si los ficheros están vacíos o cambiados de campo, parar: lo avisa el 08
const primeraApartados = $('Leer CSV de apartados').first()?.json ?? {};
const primeraVentas = $('Leer CSV de ventas').first()?.json ?? {};
if (!('modelo' in primeraApartados) || !('abono' in primeraApartados)) {
  throw new Error('El fichero de apartados no tiene las columnas esperadas (fecha, cliente, telefono, modelo, talla, precio, abono, resta, notas)');
}
if (!('concepto' in primeraVentas) || !('importe' in primeraVentas)) {
  throw new Error('El fichero de ventas no tiene las columnas esperadas (fecha, concepto, importe, forma_pago)');
}

// ---------- CSV de apartados ----------

const filasApartados = [];
$('Leer CSV de apartados').all().forEach((item, i) => {
  const r = item.json;
  const fila = i + 1;
  const datos = {
    fecha: limpiarFecha(r.fecha),
    cliente: limpiarNombre(r.cliente),
    telefono: limpiarTelefono(r.telefono),
    producto: limpiarTexto(r.modelo),
    talla: limpiarTexto(r.talla),
    precio: limpiarImporte(r.precio),
    abono: limpiarImporte(r.abono),
    resta: limpiarImporte(r.resta),
    notas: limpiarTexto(r.notas),
  };
  const resumen = `${limpiarTexto(r.fecha)} · ${limpiarTexto(r.cliente)} · ${limpiarTexto(r.modelo)} · abono ${limpiarTexto(r.abono)}`;
  let motivo = null;
  if (!datos.fecha) motivo = `no se pudo leer la fecha («${limpiarTexto(r.fecha)}»)`;
  else if (!datos.cliente || !datos.producto) motivo = 'falta el cliente o el modelo';
  else if (datos.precio === null) motivo = `no se pudo leer el precio («${limpiarTexto(r.precio)}»)`;
  else if (datos.abono === null) motivo = `no se pudo leer el abono («${limpiarTexto(r.abono)}»)`;
  if (motivo) {
    dudosos.push({ csv: 'apartados', fila, datos: resumen, motivo, notas: datos.notas });
    return;
  }
  filasApartados.push({ fila, resumen, ...datos });
});

// Agrupar por cliente normalizado + modelo, en orden de fecha
const grupos = new Map();
for (const f of filasApartados) {
  const clave = `${f.cliente.toLocaleLowerCase('es')}|${f.producto.toLocaleLowerCase('es')}`;
  if (!grupos.has(clave)) grupos.set(clave, []);
  grupos.get(clave).push(f);
}

const apartados = [];
for (const [clave, filas] of grupos) {
  filas.sort((a, b) => a.fecha.localeCompare(b.fecha) || a.fila - b.fila);
  const [primera, ...siguientes] = filas;
  if (primera.abono < ABONO_MINIMO) {
    dudosos.push({ csv: 'apartados', fila: primera.fila, datos: primera.resumen,
      motivo: `abono inicial de ${primera.abono} € (mínimo ${ABONO_MINIMO} €)`, notas: primera.notas });
    for (const s of siguientes) {
      dudosos.push({ csv: 'apartados', fila: s.fila, datos: s.resumen,
        motivo: `su apartado (fila ${primera.fila}) no se cargó`, notas: s.notas });
    }
    continue;
  }
  apartados.push({
    clave,
    fila: primera.fila,
    fecha: primera.fecha,
    cliente: primera.cliente,
    telefono: primera.telefono,
    producto: primera.producto,
    talla: primera.talla,
    precio: primera.precio,
    abono_inicial: primera.abono,
    forma_pago: 'efectivo',
    origen_forma_pago: 'efectivo por defecto',
    resta: filas[filas.length - 1].resta, // resta de la última fila, solo para comparar
    fila_resta: filas[filas.length - 1].fila,
    notas: primera.notas,
    abonos: siguientes.map(s => ({
      fila: s.fila, fecha: s.fecha, importe: s.abono,
      forma_pago: 'efectivo', origen_forma_pago: 'efectivo por defecto', notas: s.notas,
    })),
  });
}

// ---------- CSV de ventas ----------

const ventas = [];
const duplicadas = []; // filas de pagos de apartados, para tomar su forma de pago
$('Leer CSV de ventas').all().forEach((item, i) => {
  const r = item.json;
  const fila = i + 1;
  const concepto = limpiarTexto(r.concepto);
  const resumen = [limpiarTexto(r.fecha), concepto, limpiarTexto(r.importe)].filter(Boolean).join(' · ');
  if (/^total/i.test(limpiarTexto(r.fecha)) || /^total/i.test(concepto)) {
    omitidas.push({ csv: 'ventas', fila, datos: resumen, motivo: 'Fila omitida: total calculado a mano' });
    return;
  }
  const fecha = limpiarFecha(r.fecha);
  const importe = limpiarImporte(r.importe);
  const forma = limpiarTexto(r.forma_pago).toLowerCase() || 'efectivo';
  if (/abono|\(apartado\)/i.test(concepto)) {
    omitidas.push({ csv: 'ventas', fila, datos: resumen, motivo: 'Fila omitida: duplicado del CSV de apartados' });
    if (fecha && importe !== null && FORMAS_PAGO.includes(forma)) duplicadas.push({ fila, fecha, importe, forma_pago: forma });
    return;
  }
  let motivo = null;
  if (!fecha) motivo = `no se pudo leer la fecha («${limpiarTexto(r.fecha)}»)`;
  else if (!concepto) motivo = 'falta el concepto';
  else if (importe === null) motivo = `no se pudo leer el importe («${limpiarTexto(r.importe)}»)`;
  if (motivo) {
    dudosos.push({ csv: 'ventas', fila, datos: resumen, motivo, notas: '' });
    return;
  }
  ventas.push({ fila, fecha, concepto, importe, forma_pago: forma });
});

// ---------- Forma de pago de apartados y abonos (paso 6 de la spec) ----------
// Una fila duplicada que coincide por fecha + importe con exactamente un pago del CSV de apartados
// le pasa su forma de pago. Se cuentan todos los pagos limpios (también los dudosos) para saber si es único.

const pagos = [];
for (const f of filasApartados) pagos.push({ fila: f.fila, fecha: f.fecha, importe: f.abono, destino: null });
for (const a of apartados) {
  pagos.find(p => p.fila === a.fila).destino = a;
  for (const b of a.abonos) pagos.find(p => p.fila === b.fila).destino = b;
}
const asignados = new Map(); // pago → fila de ventas
for (const d of duplicadas) {
  const candidatos = pagos.filter(p => p.fecha === d.fecha && centimos(p.importe) === centimos(d.importe));
  if (candidatos.length !== 1) continue;
  const pago = candidatos[0];
  if (asignados.has(pago)) { asignados.set(pago, null); continue; } // dos filas para el mismo pago: no es único
  asignados.set(pago, d);
}
for (const [pago, d] of asignados) {
  if (!d || !pago.destino) continue;
  pago.destino.forma_pago = d.forma_pago;
  pago.destino.origen_forma_pago = `CSV de ventas, fila ${d.fila}`;
}

// ---------- Rango de fechas para las consultas a la app ----------

const fechas = [...filasApartados.map(f => f.fecha), ...ventas.map(v => v.fecha), ...duplicadas.map(d => d.fecha)].sort();
const rango = { desde: fechas[0] ?? null, hasta: fechas[fechas.length - 1] ?? null };

return [{ json: { apartados, ventas, dudosos, omitidas, rango } }];

// Code «Decidir qué crear» · Run Once for All Items
// Compara el plan con lo que ya hay en la app y marca cada apartado, abono y venta como «crear» o «ya existía».
// Devuelve un item por apartado a crear { cuerpo, ref, plan } o, si no hay ninguno, { cuerpo: null, plan }.

const plan = JSON.parse(JSON.stringify($('Limpiar y clasificar').first().json));

// Las listas vacías llegan como un item vacío (Always Output Data): se ignora
const enApp = nombre => $(nombre).all().map(i => i.json).filter(j => j && j.id != null);
const apartadosApp = enApp('Leer apartados de la app');
const abonosApp = enApp('Leer abonos de la app');
const ventasApp = enApp('Leer ventas de la app');

const nombre = v => String(v ?? '').trim().replace(/\s+/g, ' ').toLocaleLowerCase('es');
const texto = v => String(v ?? '').trim().replace(/\s+/g, ' ');
const centimos = n => Math.round(Number(n) * 100);

// Cada registro de la app solo puede «usarse» una vez (por si hay dos iguales)
const usados = new Set();
function tomar(lista, coincide, prefijo) {
  const encontrado = lista.find(x => !usados.has(`${prefijo}${x.id}`) && coincide(x));
  if (encontrado) usados.add(`${prefijo}${encontrado.id}`);
  return encontrado;
}

// Apartados: cliente normalizado + producto + talla + fecha
for (const a of plan.apartados) {
  const existente = tomar(apartadosApp, x =>
    nombre(x.cliente) === nombre(a.cliente) &&
    nombre(x.producto) === nombre(a.producto) &&
    texto(x.talla) === texto(a.talla) &&
    String(x.fecha) === a.fecha, 'apartado');
  if (existente) {
    a.estado = 'ya existía';
    a.id = existente.id;
    // Su abono inicial ya está en la app: se descuenta antes de mirar los demás abonos
    tomar(abonosApp, x => x.apartado_id === a.id && String(x.fecha) === a.fecha &&
      centimos(x.importe) === centimos(a.abono_inicial), 'abono');
  } else {
    a.estado = 'crear';
    a.id = null;
  }
  // Abonos: apartado_id + fecha + importe (si el apartado es nuevo, todos se crean)
  for (const b of a.abonos) {
    const hay = a.id != null && tomar(abonosApp, x => x.apartado_id === a.id && String(x.fecha) === b.fecha &&
      centimos(x.importe) === centimos(b.importe), 'abono');
    b.estado = hay ? 'ya existía' : 'crear';
  }
}

// Ventas: fecha + concepto + importe
for (const v of plan.ventas) {
  const hay = tomar(ventasApp, x => String(x.fecha) === v.fecha && texto(x.concepto) === v.concepto &&
    centimos(x.importe) === centimos(v.importe), 'venta');
  v.estado = hay ? 'ya existía' : 'crear';
}

// Un item por apartado a crear, con el cuerpo del POST /api/apartados
const salida = plan.apartados.filter(a => a.estado === 'crear').map(a => {
  const cuerpo = {
    cliente: a.cliente, producto: a.producto, precio: a.precio, abono_inicial: a.abono_inicial,
    forma_pago: a.forma_pago, fecha: a.fecha,
  };
  if (a.telefono) cuerpo.telefono = a.telefono;
  if (a.talla) cuerpo.talla = a.talla;
  return { json: { cuerpo, ref: { clave: a.clave, fila: a.fila }, plan } };
});

return salida.length ? salida : [{ json: { cuerpo: null, plan } }];

// Code «Preparar abonos» · Run Once for All Items
// Recoge los resultados de «Crear apartados» (si se ejecutó), apunta los id nuevos y devuelve
// un item por abono a crear { apartado_id, cuerpo, ref, plan } o, si no hay ninguno, { cuerpo: null, plan }.

const plan = JSON.parse(JSON.stringify($('Decidir qué crear').first().json.plan));
plan.errores = plan.errores ?? [];

// Resultados de un nodo, o [] si no se ejecutó (rama false del IF)
function resultadosDe(nombre) {
  try {
    if ($(nombre).isExecuted === false) return [];
    return $(nombre).all();
  } catch (e) {
    return [];
  }
}

// Mensaje de la app: {"detail": "..."} o, si falla la validación, {"detail": [{msg: ...}]}
function detalle(body) {
  let b = body;
  if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { return b; } }
  const d = b?.detail;
  if (Array.isArray(d)) return d.map(x => x.msg ?? JSON.stringify(x)).join('; ');
  return d ?? JSON.stringify(b);
}
const cuerpo = body => (typeof body === 'string' ? JSON.parse(body) : body);

// Los resultados vienen en el mismo orden que los items a crear
const aCrear = $('Decidir qué crear').all().filter(i => i.json.cuerpo);
if (aCrear.length) {
  const resultados = resultadosDe('Crear apartados');
  if (resultados.length !== aCrear.length) {
    throw new Error(`Crear apartados: se esperaban ${aCrear.length} respuestas y llegaron ${resultados.length}`);
  }
  aCrear.forEach((item, i) => {
    const a = plan.apartados.find(x => x.clave === item.json.ref.clave);
    const r = resultados[i].json;
    if (r.statusCode >= 200 && r.statusCode < 300) {
      a.estado = 'creado';
      a.id = cuerpo(r.body).id;
    } else if (r.statusCode === 422) {
      a.estado = 'error';
      a.error = detalle(r.body);
      plan.errores.push({ csv: 'apartados', fila: a.fila, datos: `${a.fecha} · ${a.cliente} · ${a.producto}`, error: a.error });
      // Sus abonos no se pueden registrar: pasan a dudosos
      for (const b of a.abonos) {
        b.estado = 'dudoso';
        plan.dudosos.push({ csv: 'apartados', fila: b.fila, datos: `${b.fecha} · ${a.cliente} · ${a.producto} · abono ${b.importe}`,
          motivo: `su apartado (fila ${a.fila}) no se cargó: la app respondió «${a.error}»`, notas: b.notas });
      }
    } else {
      // 401, 404, 5xx...: no es un problema de los datos. Se para y lo avisa el 08
      throw new Error(`Crear apartados (fila ${a.fila}): la app respondió ${r.statusCode}: ${detalle(r.body)}`);
    }
  });
}

// Un item por abono a crear de los apartados que tienen id (nuevos o que ya existían)
const salida = [];
for (const a of plan.apartados) {
  if (a.id == null) continue;
  for (const b of a.abonos) {
    if (b.estado !== 'crear') continue;
    salida.push({ json: {
      apartado_id: a.id,
      cuerpo: { importe: b.importe, forma_pago: b.forma_pago, fecha: b.fecha },
      ref: { clave: a.clave, fila: b.fila },
      plan,
    } });
  }
}

return salida.length ? salida : [{ json: { cuerpo: null, plan } }];

// Code «Preparar ventas» · Run Once for All Items
// Recoge los resultados de «Registrar abonos» (si se ejecutó) y devuelve
// un item por venta a crear { cuerpo, ref, plan } o, si no hay ninguna, { cuerpo: null, plan }.

const plan = JSON.parse(JSON.stringify($('Preparar abonos').first().json.plan));

// Resultados de un nodo, o [] si no se ejecutó (rama false del IF)
function resultadosDe(nombre) {
  try {
    if ($(nombre).isExecuted === false) return [];
    return $(nombre).all();
  } catch (e) {
    return [];
  }
}

function detalle(body) {
  let b = body;
  if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { return b; } }
  const d = b?.detail;
  if (Array.isArray(d)) return d.map(x => x.msg ?? JSON.stringify(x)).join('; ');
  return d ?? JSON.stringify(b);
}

// Los resultados vienen en el mismo orden que los abonos a crear
const aCrear = $('Preparar abonos').all().filter(i => i.json.cuerpo);
if (aCrear.length) {
  const resultados = resultadosDe('Registrar abonos');
  if (resultados.length !== aCrear.length) {
    throw new Error(`Registrar abonos: se esperaban ${aCrear.length} respuestas y llegaron ${resultados.length}`);
  }
  aCrear.forEach((item, i) => {
    const a = plan.apartados.find(x => x.clave === item.json.ref.clave);
    const b = a.abonos.find(x => x.fila === item.json.ref.fila);
    const r = resultados[i].json;
    if (r.statusCode >= 200 && r.statusCode < 300) {
      b.estado = 'creado';
    } else if (r.statusCode === 422) {
      b.estado = 'error';
      b.error = detalle(r.body);
      plan.errores.push({ csv: 'apartados', fila: b.fila, datos: `${b.fecha} · ${a.cliente} · ${a.producto} · abono ${b.importe}`, error: b.error });
    } else {
      throw new Error(`Registrar abonos (fila ${b.fila}): la app respondió ${r.statusCode}: ${detalle(r.body)}`);
    }
  });
}

const salida = plan.ventas.filter(v => v.estado === 'crear').map(v => ({ json: {
  cuerpo: { concepto: v.concepto, importe: v.importe, forma_pago: v.forma_pago, fecha: v.fecha },
  ref: { fila: v.fila },
  plan,
} }));

return salida.length ? salida : [{ json: { cuerpo: null, plan } }];

// Code «Preparar informe» · Run Once for All Items
// Recoge los resultados de «Registrar ventas» (si se ejecutó), compara el pendiente de la app con la resta
// del Excel y devuelve { asunto, texto } para el correo. No recalcula nada: el pendiente es el de la app.

const plan = JSON.parse(JSON.stringify($('Preparar ventas').first().json.plan));

// Resultados de un nodo, o [] si no se ejecutó (rama false del IF)
function resultadosDe(nombre) {
  try {
    if ($(nombre).isExecuted === false) return [];
    return $(nombre).all();
  } catch (e) {
    return [];
  }
}

function detalle(body) {
  let b = body;
  if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { return b; } }
  const d = b?.detail;
  if (Array.isArray(d)) return d.map(x => x.msg ?? JSON.stringify(x)).join('; ');
  return d ?? JSON.stringify(b);
}

// Resultados de las ventas, en el mismo orden que los items a crear
const aCrear = $('Preparar ventas').all().filter(i => i.json.cuerpo);
if (aCrear.length) {
  const resultados = resultadosDe('Registrar ventas');
  if (resultados.length !== aCrear.length) {
    throw new Error(`Registrar ventas: se esperaban ${aCrear.length} respuestas y llegaron ${resultados.length}`);
  }
  aCrear.forEach((item, i) => {
    const v = plan.ventas.find(x => x.fila === item.json.ref.fila);
    const r = resultados[i].json;
    if (r.statusCode >= 200 && r.statusCode < 300) {
      v.estado = 'creado';
    } else if (r.statusCode === 422) {
      v.estado = 'error';
      v.error = detalle(r.body);
      plan.errores.push({ csv: 'ventas', fila: v.fila, datos: `${v.fecha} · ${v.concepto} · ${v.importe}`, error: v.error });
    } else {
      throw new Error(`Registrar ventas (fila ${v.fila}): la app respondió ${r.statusCode}: ${detalle(r.body)}`);
    }
  });
}

// Pendiente de la app frente a la resta del Excel
const apartadosApp = $('Comprobar pendientes').all().map(i => i.json).filter(j => j && j.id != null);
const diferencias = [];
const sinComprobar = [];
for (const a of plan.apartados) {
  if (a.id == null) continue;
  const enApp = apartadosApp.find(x => x.id === a.id);
  if (!enApp) { sinComprobar.push(`- ${a.cliente} · ${a.producto} (id ${a.id}): no aparece en la app`); continue; }
  a.pendiente_app = enApp.pendiente;
  if (a.resta === null || a.resta === undefined) { sinComprobar.push(`- ${a.cliente} · ${a.producto} (id ${a.id}): el Excel no tiene resta`); continue; }
  if (Math.round(enApp.pendiente * 100) !== Math.round(a.resta * 100)) {
    diferencias.push(`- ${a.cliente} · ${a.producto} (id ${a.id}): pendiente en la app ${enApp.pendiente.toFixed(2)} € · resta en el Excel ${a.resta.toFixed(2)} € (fila ${a.fila_resta})`);
  }
}

// ---------- Texto del informe ----------

const e = n => `${Number(n).toFixed(2)} €`;
const pago = x => `${x.forma_pago} (${x.origen_forma_pago})`;
const lineaApartado = a => `- ${a.id != null ? `#${a.id} · ` : ''}${a.fecha} · ${a.cliente} · ${a.producto}${a.talla ? ` T${a.talla}` : ''} · precio ${e(a.precio)} · abono inicial ${e(a.abono_inicial)} · ${pago(a)} (fila ${a.fila})`;
const abonos = plan.apartados.flatMap(a => a.abonos.map(b => ({ a, b })));
const lineaAbono = ({ a, b }) => `- ${b.fecha} · ${a.cliente} · ${a.producto} · ${e(b.importe)} · ${pago(b)} (fila ${b.fila})`;
const lineaVenta = v => `- ${v.fecha} · ${v.concepto} · ${e(v.importe)} · ${v.forma_pago} (fila ${v.fila})`;

function seccion(titulo, lineas) {
  return `${titulo} (${lineas.length})\n${lineas.length ? lineas.join('\n') : '- Ninguno'}\n`;
}

const creados = {
  apartados: plan.apartados.filter(a => a.estado === 'creado'),
  abonos: abonos.filter(x => x.b.estado === 'creado'),
  ventas: plan.ventas.filter(v => v.estado === 'creado'),
};
const existian = {
  apartados: plan.apartados.filter(a => a.estado === 'ya existía'),
  abonos: abonos.filter(x => x.b.estado === 'ya existía'),
  ventas: plan.ventas.filter(v => v.estado === 'ya existía'),
};

const texto = [
  'Informe de la migración del Excel',
  '',
  'CREADOS',
  seccion('Apartados', creados.apartados.map(lineaApartado)),
  seccion('Abonos (sin contar los iniciales)', creados.abonos.map(lineaAbono)),
  seccion('Ventas', creados.ventas.map(lineaVenta)),
  'YA EXISTÍAN (no se han vuelto a crear)',
  seccion('Apartados', existian.apartados.map(lineaApartado)),
  seccion('Abonos', existian.abonos.map(lineaAbono)),
  seccion('Ventas', existian.ventas.map(lineaVenta)),
  seccion('DUDOSOS (no se han cargado: decide Marisa)', plan.dudosos.map(d =>
    `- CSV de ${d.csv}, fila ${d.fila}: ${d.datos}. Motivo: ${d.motivo}${d.notas ? `. Notas: «${d.notas}»` : ''}`)),
  seccion('FILAS OMITIDAS', plan.omitidas.map(o => `- CSV de ${o.csv}, fila ${o.fila}: ${o.datos}. ${o.motivo}`)),
  seccion('DIFERENCIAS CON LA RESTA DEL EXCEL (no se corrigen)', diferencias),
  ...(sinComprobar.length ? [seccion('SIN COMPROBAR', sinComprobar)] : []),
  seccion('ERRORES DE LA API (422)', plan.errores.map(x => `- CSV de ${x.csv}, fila ${x.fila}: ${x.datos}. La app respondió: «${x.error}»`)),
].join('\n');

const asunto = `Migración del Excel: ${creados.apartados.length} apartados, ${creados.abonos.length} abonos y ${creados.ventas.length} ventas creados · ${plan.dudosos.length} dudosos · ${plan.errores.length} errores`;

return [{ json: { asunto, texto } }];
